#!/usr/bin/env python3
"""RF受信ユニットのチャンネルを定義順に周期切替する。

Usage:
    python3 channel_cycle.py 192.0.2.10 60
    python3 channel_cycle.py http://192.0.2.10:8080 60 --once
"""

import argparse
import json
import logging
import signal
import sys
import threading
import time
from collections import namedtuple
from typing import Any, Dict, List
from urllib.error import HTTPError, URLError
from urllib.parse import urlencode, urlsplit
from urllib.request import Request, urlopen


LOG = logging.getLogger("channel_cycle")


class ApiError(RuntimeError):
    """RF受信ユニットAPIが返したエラー。"""


Channel = namedtuple("Channel", "name physical_channel tsid sid order")
"""/api/chlist の1件分のチャンネル定義。Python 3.6でも動作する不変の値オブジェクト。"""


def parse_number(value: Any, field_name: str) -> int:
    """APIの10進数または 0x 接頭辞付き16進数を整数へ変換する。"""
    if isinstance(value, bool):
        raise ValueError("{} must be a number".format(field_name))
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        text = value.strip()
        base = 16 if text.lower().startswith("0x") else 10
        return int(text, base)
    raise ValueError("{} must be a number".format(field_name))


def normalize_base_url(address: str) -> str:
    """ホスト名/IPアドレスまたは完全なHTTP URLをベースURLへ正規化する。"""
    candidate = address if "://" in address else "http://" + address
    parsed = urlsplit(candidate)
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        raise ValueError("address must be a host[:port] or an HTTP(S) URL")
    if parsed.path not in ("", "/") or parsed.query or parsed.fragment:
        raise ValueError("address must not include a path, query, or fragment")
    return "{}://{}".format(parsed.scheme, parsed.netloc)


def request_json(url: str, timeout: float, form: Dict[str, Any] = None) -> Dict[str, Any]:
    """JSON APIを呼び出し、共通エラー応答も検査する。"""
    data = None
    headers = {"Accept": "application/json"}
    if form is not None:
        data = urlencode(form).encode("utf-8")
        headers["Content-Type"] = "application/x-www-form-urlencoded"

    request = Request(url, data=data, headers=headers, method="POST" if data else "GET")
    body = request.data.decode("utf-8") if request.data else ""
    LOG.debug(
        "HTTP request:\n%s %s\nHeaders: %s\nBody: %s",
        request.get_method(), request.full_url,
        json.dumps(dict(request.header_items()), ensure_ascii=False, sort_keys=True),
        body if body else "<empty>",
    )
    try:
        with urlopen(request, timeout=timeout) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        raise ApiError("HTTP {} from {}: {}".format(exc.code, url, body)) from exc
    except (URLError, TimeoutError, json.JSONDecodeError) as exc:
        raise ApiError("request to {} failed: {}".format(url, exc)) from exc

    if not isinstance(payload, dict):
        raise ApiError("unexpected JSON response from {}".format(url))
    if payload.get("error"):
        raise ApiError("API error from {}: {}".format(url, payload.get("err_msg", "unknown error")))
    return payload


def fetch_channels(base_url: str, timeout: float) -> List[Channel]:
    """ユニットからチャンネル定義を取得して巡回順に整列する。"""
    payload = request_json(base_url + "/api/chlist", timeout)
    definitions = payload.get("result")
    if not isinstance(definitions, list) or not definitions:
        raise ApiError("/api/chlist returned no channel definitions")

    channels = []
    for index, item in enumerate(definitions):
        if not isinstance(item, dict):
            raise ApiError("channel definition #{} is not an object".format(index))
        try:
            name = str(item["name"])
            physical_channel = str(item["ch"])
            if not name or not physical_channel:
                raise ValueError("name and ch must not be empty")
            channels.append(Channel(
                name=name,
                physical_channel=physical_channel,
                tsid=parse_number(item["tsid"], "tsid"),
                sid=parse_number(item["sid"], "sid"),
                order=parse_number(item.get("order", item["idx"]), "order"),
            ))
        except (KeyError, TypeError, ValueError) as exc:
            raise ApiError("invalid channel definition #{}: {}".format(index, exc)) from exc

    return sorted(channels, key=lambda channel: channel.order)


def switch_channel(base_url: str, channel: Channel, timeout: float) -> None:
    """指定チャンネルへの切替を要求する。"""
    request_json(base_url + "/api/changech", timeout, {
        "CHANNEL": channel.physical_channel,
        "TSID": channel.tsid,
        "SID": channel.sid,
        "CH-NAME": channel.name,
    })


def fetch_rf_status(base_url: str, timeout: float) -> Dict[str, Any]:
    """ユニットから現在のRF状態を取得する。"""
    return request_json(base_url + "/api/rfstate", timeout)


def poll_rf_status(base_url: str, duration: float, timeout: float,
                   stop_event: threading.Event) -> None:
    """次のチャンネル切替までRF状態を1秒ごとに標準出力へ出力する。"""
    deadline = time.monotonic() + duration
    next_poll = time.monotonic() + 1.0

    while not stop_event.is_set():
        remaining = next_poll - time.monotonic()
        if remaining > 0 and stop_event.wait(remaining):
            return
        if time.monotonic() >= deadline:
            return

        try:
            # APIエンベロープ（error、err_msg、result）をそのままJSON Linesで出力する。
            print(json.dumps(fetch_rf_status(base_url, timeout), ensure_ascii=False), flush=True)
        except ApiError as exc:
            LOG.error("RF status request failed: %s", exc)

        next_poll += 1.0


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="RF受信ユニットのチャンネルを周期的に切り替えます。")
    parser.add_argument("address", help="対象ユニットのIPアドレスまたは http(s)://host[:port]")
    parser.add_argument("period", type=float, help="チャンネル切替周期（秒。0より大きい値）")
    parser.add_argument("--timeout", type=float, default=10.0, help="各HTTP要求のタイムアウト秒（既定: 10）")
    parser.add_argument("--once", action="store_true",
                        help="先頭のチャンネルへ1回だけ切り替え、指定周期の間RF状態を出力して終了")
    parser.add_argument("--verbose", action="store_true",
                        help="HTTPリクエストのメソッド・URL・ヘッダー・ボディを含む詳細ログを出力")
    args = parser.parse_args()
    if args.period <= 0:
        parser.error("period must be greater than zero")
    if args.timeout <= 0:
        parser.error("--timeout must be greater than zero")
    return args


def main() -> int:
    args = parse_args()
    logging.basicConfig(
        level=logging.DEBUG if args.verbose else logging.INFO,
        format="%(asctime)s %(levelname)s %(message)s",
    )
    try:
        base_url = normalize_base_url(args.address)
        channels = fetch_channels(base_url, args.timeout)
    except (ValueError, ApiError) as exc:
        LOG.error("initialization failed: %s", exc)
        return 1

    LOG.info("loaded %d channel definition(s) from %s", len(channels), base_url)
    stop_event = threading.Event()

    def stop_handler(signum: int, _frame: Any) -> None:
        LOG.info("received signal %s; stopping", signum)
        stop_event.set()

    signal.signal(signal.SIGINT, stop_handler)
    signal.signal(signal.SIGTERM, stop_handler)

    index = 0
    while not stop_event.is_set():
        channel = channels[index]
        switched = false
        try:
            switch_channel(base_url, channel, args.timeout)
            LOG.info("switch requested: %s (physical channel=%s, TSID=0x%04X, SID=0x%04X)",
                     channel.name, channel.physical_channel, channel.tsid, channel.sid)
            index = (index + 1) % len(channels)
            switched = true
        except ApiError as exc:
            # 同じチャンネルを次周期に再試行し、失敗時に巡回位置を進めない。
            LOG.error("channel switch failed: %s", exc)

        # 切替成功時だけ、次の切替まで1秒ごとにRF状態を取得する。
        # 切替失敗時は従来どおり指定周期を待って同じチャンネルを再試行する。
        if switched:
            poll_rf_status(base_url, args.period, args.timeout, stop_event)
        else:
            stop_event.wait(args.period)

        if args.once:
            break

    return 0


if __name__ == "__main__":
    sys.exit(main())

